-- Routes Cloudflare Email Sending events, which carry only the provider's message id,
-- back to the send in its Organization's Durable Object.
CREATE TABLE email_message (
  message_id TEXT NOT NULL PRIMARY KEY,
  organization_id TEXT NOT NULL,
  send_id TEXT NOT NULL
) WITHOUT ROWID;

-- Every stage except production records its email here instead of sending it (docs/infra.md).
CREATE TABLE captured_email (
  message_id TEXT NOT NULL PRIMARY KEY,
  recipient TEXT NOT NULL,
  subject TEXT NOT NULL,
  html TEXT NOT NULL,
  text TEXT NOT NULL,
  captured_at INTEGER NOT NULL
) WITHOUT ROWID;
CREATE TABLE organization (
  id TEXT NOT NULL PRIMARY KEY,
  name TEXT NOT NULL
) WITHOUT ROWID;
-- One row per transactional send (ADR 0006). `state` is the domain's SendState as JSON;
-- `status` repeats its tag so a Lead's view can list failed sends without decoding every row.
CREATE TABLE email_send (
  id TEXT NOT NULL PRIMARY KEY,
  recipient TEXT NOT NULL,
  content TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('Pending', 'Sending', 'Sent', 'Failed')),
  state TEXT NOT NULL
) WITHOUT ROWID;

import * as Cloudflare from "@alchemy.run/cloudflare";
import { SqliteClient } from "@effect/sql-sqlite-do";
import {
  defaultSendPolicy,
  type DeliveryEventKind,
  type EmailAddress,
  makeSendStore,
  type SendId,
  type SendOutcome,
  type TransactionalEmail,
} from "@surveybeat/domain";
import * as Effect from "effect/Effect";
import * as Option from "effect/Option";
import * as Reactivity from "effect/reactivity/Reactivity";
import * as Scope from "effect/Scope";
import { makeSqlSendRepository } from "./SqlSendRepository.ts";

/**
 * Relative to the directory Alchemy runs in, which is the repository root (`pnpm infra:deploy`, `pnpm test`).
 * It must be a literal: the same expression runs again inside the bundle, where `import.meta.url` differs.
 */
const migrationsDirectory = "packages/cloudflare/migrations";

/**
 * The Organization Durable Object (ADR 0006): one object per Organization, SQLite storage.
 * Methods return plain data (no `Option`), because they cross the RPC boundary.
 * The Main Worker maps it to the domain schemas.
 */
export default class Organization extends Cloudflare.DurableObject<Organization>()(
  "Organization",
  Effect.gen(function* () {
    // Outer phase: capture the SQL files into the bundle.
    const migrations = yield* Cloudflare.SqlMigrations(migrationsDirectory);

    // Inner phase: runs once per object activation, before any method is exposed.
    return Effect.gen(function* () {
      const state = yield* Cloudflare.DurableObjectState;

      // Pass `storage` (not just `db`) so `withTransaction` uses `storage.transaction()`.
      const scope = yield* Scope.make();
      const sql = yield* SqliteClient.make({ storage: state.raw.storage }).pipe(
        Effect.provideService(Scope.Scope, scope),
        Effect.provide(Reactivity.layer),
      );

      yield* migrations.apply().pipe(Effect.orDie);

      // Transactional email: the domain's SendStore on this object's `email_send` table.
      const sends = makeSendStore(makeSqlSendRepository(sql), defaultSendPolicy);

      return {
        create: (id: string, name: string) =>
          sql
            .withTransaction(sql`INSERT INTO organization (id, name) VALUES (${id}, ${name})`)
            .pipe(Effect.as({ id, name }), Effect.orDie),

        get: (id: string) =>
          sql<{ id: string; name: string }>`SELECT id, name FROM organization WHERE id = ${id}`.pipe(
            Effect.map((rows) => rows[0] ?? null),
            Effect.orDie,
          ),

        createEmailSend: (id: SendId, recipient: EmailAddress, email: TransactionalEmail) =>
          sends.create(id, recipient, email),
        getEmailSend: (id: SendId) => sends.get(id).pipe(Effect.map(Option.getOrNull)),
        claimEmailSend: (id: SendId, now: number) => sends.claim(id, now),
        settleEmailSend: (id: SendId, attempt: number, outcome: SendOutcome, now: number) =>
          sends.settle(id, attempt, outcome, now).pipe(Effect.map(Option.getOrNull)),
        abandonEmailSend: (id: SendId, now: number) =>
          sends.abandon(id, now).pipe(Effect.map(Option.getOrNull)),
        recordEmailDeliveryEvent: (id: SendId, kind: DeliveryEventKind, code: string | null, now: number) =>
          sends.recordDeliveryEvent(id, kind, code, now).pipe(Effect.map(Option.getOrNull)),
      };
    });
  }),
) {}
import * as Cloudflare from "@alchemy.run/cloudflare";
import * as Test from "@alchemy.run/test/Vitest";
import { SurveyBeatApi } from "@surveybeat/api";
import { OrganizationId } from "@surveybeat/domain";
import * as Alchemy from "alchemy";
import { assert } from "@effect/vitest";
import * as Effect from "effect/Effect";
import * as HttpApiClient from "effect/http-api/HttpApiClient";
import MainWorker from "./MainWorker.ts";

// The adapter on local workerd (`dev: true`): the real Main Worker and Organization Durable Object.
const { test, beforeAll, deploy } = Test.make({
  providers: Cloudflare.providers(),
  dev: true,
});

const Stack = Alchemy.Stack(
  "SurveybeatOrganizationTest",
  { providers: Cloudflare.providers(), state: Alchemy.localState() },
  Effect.gen(function* () {
    const main = yield* MainWorker;
    return { url: main.url.as<string>() };
  }),
);

const stack = beforeAll(deploy(Stack), { timeout: 240_000 });

const makeClient = Effect.gen(function* () {
  const { url } = yield* stack;
  return yield* HttpApiClient.make(SurveyBeatApi, { baseUrl: url });
});

test(
  "creates an Organization and reads it back",
  Effect.gen(function* () {
    const client = yield* makeClient;
    const created = yield* client.organizations.create({ payload: { name: "Acme" } });
    assert.strictEqual(created.name, "Acme");
    const fetched = yield* client.organizations.getById({ params: { id: created.id } });
    assert.deepStrictEqual(fetched, created);
  }),
);

test(
  "answers OrganizationNotFound for an unknown or malformed id",
  Effect.gen(function* () {
    const client = yield* makeClient;
    for (const id of ["0".repeat(32), "not-an-id"]) {
      const error = yield* client.organizations
        .getById({ params: { id: OrganizationId.make(id) } })
        .pipe(Effect.flip);
      assert.strictEqual(error._tag, "OrganizationNotFound");
    }
  }),
);
import type * as Cloudflare from "@alchemy.run/cloudflare";
import { EmailAddress, OrganizationId, SendId } from "@surveybeat/domain";
import * as Effect from "effect/Effect";
import { HttpServerRequest } from "effect/http/HttpServerRequest";
import * as HttpServerResponse from "effect/http/HttpServerResponse";
import { type Organizations, queueEmail } from "./EmailDelivery.ts";

/** Stages that `@alchemy.run/test` creates (`test_$USER…`). No other stage gets these routes. */
export const isTestStage = (stage: string): boolean => stage.startsWith("test_");

export const TEST_ROUTES = "/__test/email";

/**
 * Test-only routes for the email adapter test on local workerd (ADR 0008): `POST` queues an
 * "added to team" email to `ada@example.com`; `GET` reads the send back with what was captured.
 */
export const emailTestRoutes = (
  organizations: Organizations,
  queue: Cloudflare.Queues.WriteQueueClient,
  db: Cloudflare.D1.QueryDatabaseClient,
) =>
  Effect.gen(function* () {
    const request = yield* HttpServerRequest;
    const params = new URL(request.url, "http://localhost").searchParams;
    const organizationId = OrganizationId.make(params.get("organization") ?? "");
    const sendId = SendId.make(params.get("send") ?? "");
    if (request.method === "POST") {
      const state = yield* queueEmail(organizations, queue, {
        organizationId,
        sendId,
        recipient: EmailAddress.make("ada@example.com"),
        email: {
          _tag: "AddedToTeam",
          teamName: "Platform",
          leadName: "Grace Hopper",
          signInUrl: "https://app.surveybeat.app/",
        },
      });
      return yield* HttpServerResponse.json({ state });
    }
    const record = yield* organizations.getByName(organizationId).getEmailSend(sendId);
    const messageId = record?.state._tag === "Sent" ? record.state.messageId : "";
    const captured = yield* db
      .prepare("SELECT recipient, subject, text FROM captured_email WHERE message_id = ?")
      .bind(messageId)
      .all();
    const indexed = yield* db
      .prepare("SELECT organization_id, send_id FROM email_message WHERE message_id = ?")
      .bind(messageId)
      .all();
    return yield* HttpServerResponse.json({
      state: record?.state ?? null,
      captured: captured.results,
      indexed: indexed.results,
    });
  }).pipe(Effect.orDie);
import type * as Cloudflare from "@alchemy.run/cloudflare";
import { EmailSender } from "@surveybeat/domain";
import type { RuntimeContext } from "alchemy/RuntimeContext";
import * as Clock from "effect/Clock";
import * as Effect from "effect/Effect";

/**
 * `EmailSender` for every stage except production: records each message in the `captured_email`
 * table of the stage's D1 database and sends nothing. Built inside a handler.
 */
export const capturingEmailSender = (db: Cloudflare.D1.QueryDatabaseClient) =>
  Effect.gen(function* () {
    const runtime = yield* Effect.context<RuntimeContext>();
    return EmailSender.of({
      send: (message) =>
        Effect.gen(function* () {
          const messageId = `captured-${crypto.randomUUID()}`;
          yield* db
            .prepare(
              "INSERT INTO captured_email (message_id, recipient, subject, html, text, captured_at) VALUES (?, ?, ?, ?, ?, ?)",
            )
            .bind(
              messageId,
              message.to,
              message.subject,
              message.html,
              message.text,
              yield* Clock.currentTimeMillis,
            )
            .run();
          return { messageId };
        }).pipe(Effect.provideContext(runtime)),
    });
  });
import * as Cloudflare from "@alchemy.run/cloudflare";
import { OrganizationId, SendId } from "@surveybeat/domain";
import { Stack } from "alchemy/Stack";
import * as Effect from "effect/Effect";
import * as Schema from "effect/Schema";
import { ZONE, ZONE_ID } from "./Hostnames.ts";

/** Only production sends real email. Every other stage records messages instead (docs/infra.md). */
export const sendsRealEmail = (stage: string): boolean => stage === "production";

/** The sending subdomain. The apex keeps its own mail, SPF, and DMARC records untouched. */
export const SENDING_DOMAIN = `notify.${ZONE}`;
export const FROM = { email: `team@${SENDING_DOMAIN}`, name: "SurveyBeat" } as const;

/** The `send_email` binding. Bound to the Main Worker in production only. */
export const SendEmail = Cloudflare.Email.SendEmail("Email");

/** One message per send. The consumer looks the send up in its Organization's Durable Object. */
export const EmailQueue = Cloudflare.Queues.Queue("Email");
/** Messages the consumer gave up on. Their sends are failed, never left pending. */
export const EmailQueueDlq = Cloudflare.Queues.Queue("EmailDlq");
/** Cloudflare Email Sending events (bounces, complaints) for the sending subdomain. Production only. */
export const EmailEvents = Cloudflare.Queues.Queue("EmailEvents");

export const EmailSendRequested = Schema.Struct({ organizationId: OrganizationId, sendId: SendId });
export type EmailSendRequested = typeof EmailSendRequested.Type;

/**
 * Production only: the sending subdomain (Cloudflare creates its DKIM, SPF, DMARC, and bounce
 * records under `notify.`, never at the apex) and the event subscription that feeds bounces and
 * complaints into `EmailEvents`. Other stages provision neither.
 */
export const ProductionEmail = Effect.gen(function* () {
  const { stage } = yield* Stack;
  if (!sendsRealEmail(stage)) return undefined;
  const subdomain = yield* Cloudflare.Email.SendingSubdomain("Notify", {
    zoneId: ZONE_ID,
    name: SENDING_DOMAIN,
    // Cloudflare would otherwise keep each message, invitation links included, for about a week.
    previewEnabled: false,
  });
  const events = yield* EmailEvents;
  yield* Cloudflare.Queues.Subscription("EmailEventsSubscription", {
    source: { type: "email.sending", zoneId: ZONE_ID, domain: SENDING_DOMAIN },
    events: ["message.bounced", "message.complained", "message.rejected", "message.failed"],
    queueId: events.queueId,
  });
  return subdomain;
});

