describe("the per-request session check", () => {
  const signedIn = async () => {
    const context = setup();
    const acme = context.world.addOrganization("Acme");
    const personId = context.world.addPerson(acme.id, "ada@example.com");
    await context.browser.signIn(context.world.workos.addUser("ada@example.com"));
    expect((await context.browser.session()).status).toBe(200);
    return { ...context, acme, personId };
  };

  it("denies a signed-out session on the next request, although its access token is still valid", async () => {
    const { world, browser, newBrowser } = await signedIn();
    const stolen = browser.cookies.get(SESSION_COOKIE) ?? "";

    const logout = await browser.fetch("/auth/logout", { method: "POST", headers: { origin: ORIGIN } });
    expect(logout.status).toBe(303);
    expect(logout.headers.get("location")).toMatch(/^https:\/\/auth\.example\.test\/logout\?session_id=session_/);
    expect(browser.cookies.has(SESSION_COOKIE)).toBe(false);

    // The fake still accepts the token, as WorkOS's JWT would until it expires: our deny list decides.
    expect(world.workos.sessions.has(stolen)).toBe(true);
    const replay = newBrowser();
    replay.cookies.set(SESSION_COOKIE, stolen);
    expect((await replay.session()).status).toBe(401);
  });

  it("denies the session on the next request once the Person is removed from the Organization", async () => {
    const { world, browser, acme, personId } = await signedIn();
    const person = world.durable.person(acme.id, personId);
    if (person === undefined) throw new Error("no person");
    person.removed = true;
    const denied = await browser.get("/auth/session");
    expect(denied.status).toBe(401);
    expect(browser.cookies.has(SESSION_COOKIE)).toBe(false);
  });

  it("refreshes an expired access token and writes the rotated cookie", async () => {
    const { world, browser } = await signedIn();
    const before = browser.cookies.get(SESSION_COOKIE) ?? "";
    world.workos.expire(before);
    expect((await browser.session()).body).toMatchObject({ _tag: "SignedIn" });
    const after = browser.cookies.get(SESSION_COOKIE);
    expect(after).toBeDefined();
    expect(after).not.toBe(before);
    expect((await browser.session()).status).toBe(200);
  });

  it("signs out a session whose refresh token is gone", async () => {
    const { world, browser } = await signedIn();
    const sealed = browser.cookies.get(SESSION_COOKIE) ?? "";
    world.workos.expire(sealed);
    world.workos.sessions.delete(sealed);
    expect((await browser.session()).status).toBe(401);
  });

  it("refuses state-changing requests from another origin", async () => {
    const { world, browser } = setup("ops@example.com");
    await browser.signIn(world.workos.addUser("ops@example.com"));
    const response = await browser.post("/auth/organization", { name: "Acme" }, "https://pr-1.submit.surveybeat.app");
    expect(response.status).toBe(403);
    expect(world.workos.createOrganizationCalls).toBe(0);
  });
});

import type * as Cloudflare from "@alchemy.run/cloudflare";
import { assert, describe, it } from "@effect/vitest";
import {
  EmailAddress,
  OrganizationId,
  PeopleIndex,
  PersonId,
  SessionId,
  WorkosOrganizationId,
  WorkosUserId,
} from "@surveybeat/domain";
import { RuntimeContext } from "alchemy/RuntimeContext";
import * as Effect from "effect/Effect";
import * as Option from "effect/Option";
import { readdirSync, readFileSync } from "node:fs";
import { DatabaseSync } from "node:sqlite";
import { d1PeopleIndex } from "./D1PeopleIndex.ts";

// The D1 adapter's SQL against the real migrations, on Node's SQLite (the engine D1 runs).
const migrations = new URL("../../d1-migrations/", import.meta.url);

const makeIndex = () => {
  const sqlite = new DatabaseSync(":memory:");
  for (const file of readdirSync(migrations).sort()) sqlite.exec(readFileSync(new URL(file, migrations), "utf8"));
  const statement = (sql: string, binds: ReadonlyArray<unknown>) => ({
    bind: (...values: ReadonlyArray<unknown>) => statement(sql, values),
    all: () => Effect.sync(() => ({ results: sqlite.prepare(sql).all(...(binds as Array<null | string | number>)) })),
    run: () => Effect.sync(() => (sqlite.prepare(sql).run(...(binds as Array<null | string | number>)), { results: [] })),
  });
  const client = { prepare: (sql: string) => statement(sql, []) } as unknown as Cloudflare.D1.QueryDatabaseClient;
  return d1PeopleIndex(client).pipe(Effect.provideService(RuntimeContext, {} as RuntimeContext));
};

const acme = { id: OrganizationId.make("acme"), name: "Acme" };
const globex = { id: OrganizationId.make("globex"), name: "Globex" };
const ada = WorkosUserId.make("user_ada");

describe("D1 PeopleIndex", () => {
  it.effect("finds unlinked Persons by normalised email, then by user once linked", () =>
    Effect.gen(function* () {
      const index = yield* makeIndex();
      yield* index.putOrganization(acme, Option.some(WorkosOrganizationId.make("org_acme")));
      yield* index.putOrganization(globex, Option.none());
      const person = PersonId.make("p1");
      yield* index.putPerson({
        organizationId: acme.id,
        personId: person,
        email: EmailAddress.make("Ada@Example.com"),
        userId: Option.none(),
      });
      yield* index.putPerson({
        organizationId: globex.id,
        personId: PersonId.make("p2"),
        email: EmailAddress.make("ada@example.com"),
        userId: Option.none(),
      });

      const unlinked = yield* index.unlinkedPersons(EmailAddress.make("ADA@example.com"));
      assert.deepStrictEqual(
        unlinked.map((candidate) => candidate.organization.id),
        [acme.id, globex.id],
      );

      yield* index.linkPerson(acme.id, person, ada);
      // Linking is one-shot: a second user cannot take the Person over.
      yield* index.linkPerson(acme.id, person, WorkosUserId.make("user_mallory"));
      assert.deepStrictEqual(yield* index.linkedPersons(ada), [
        { organization: acme, personId: person, linked: true },
      ]);
      assert.deepStrictEqual(
        (yield* index.unlinkedPersons(EmailAddress.make("ada@example.com"))).map((c) => c.organization.id),
        [globex.id],
      );
    }),
  );

  it.effect("maps WorkOS organizations both ways, and keeps a known WorkOS id when re-put without one", () =>
    Effect.gen(function* () {
      const index = yield* makeIndex();
      const workos = WorkosOrganizationId.make("org_acme");
      yield* index.putOrganization(acme, Option.none());
      assert.isTrue(Option.isNone(yield* index.workosOrganizationOf(acme.id)));
      yield* index.putOrganization(acme, Option.some(workos));
      yield* index.putOrganization(acme, Option.none());
      assert.deepStrictEqual(yield* index.workosOrganizationOf(acme.id), Option.some(workos));
      assert.deepStrictEqual(yield* index.organizationByWorkos(workos), Option.some(acme));
    }),
  );

  it.effect("keeps the first Organization claim of a user", () =>
    Effect.gen(function* () {
      const index = yield* makeIndex();
      const first = { organization: acme, adminPersonId: PersonId.make("admin-1") };
      const second = { organization: globex, adminPersonId: PersonId.make("admin-2") };
      const [a, b] = yield* Effect.all([index.claimOrganization(ada, first), index.claimOrganization(ada, second)], {
        concurrency: "unbounded",
      });
      assert.deepStrictEqual(a, first);
      assert.deepStrictEqual(b, first);
      assert.deepStrictEqual(yield* index.claimOf(ada), Option.some(first));
    }),
  );

  it.effect("records revoked sessions", () =>
    Effect.gen(function* () {
      const index = yield* makeIndex();
      const session = SessionId.make("session_1");
      assert.isFalse(yield* index.isSessionRevoked(session));
      yield* index.revokeSession(session, 1);
      yield* index.revokeSession(session, 2);
      assert.isTrue(yield* index.isSessionRevoked(session));
    }),
  );

  it.effect("rejects an email stored without normalising", () =>
    Effect.gen(function* () {
      const sqlite = new DatabaseSync(":memory:");
      for (const file of readdirSync(migrations).sort()) {
        sqlite.exec(readFileSync(new URL(file, migrations), "utf8"));
      }
      assert.throws(() =>
        sqlite
          .prepare("INSERT INTO person_index (organization_id, person_id, email) VALUES ('a', 'p', 'Ada@x.com')")
          .run(),
      );
      void PeopleIndex;
    }),
  );
});

import { describe, expect, it } from "@effect/vitest";
import { EmailAddress } from "../email/Email.ts";
import { type Identity, OrganizationCreationAllowlist, PersonId, WorkosUserId } from "./Identity.ts";
import { OrganizationId } from "./Organization.ts";
import { candidatesFor, decideSignIn, type PersonCandidate } from "./SignIn.ts";

const identity = (emailVerified: boolean, email = "ada@example.com"): Identity => ({
  userId: WorkosUserId.make("user_1"),
  email: EmailAddress.make(email),
  emailVerified,
});

const candidate = (organization: string, linked: boolean): PersonCandidate => ({
  organization: { id: OrganizationId.make(organization), name: organization },
  personId: PersonId.make(`${organization}-person`),
  linked,
});

const nobody = new OrganizationCreationAllowlist("");

describe("candidatesFor", () => {
  it("ignores email matches for an unverified email", () => {
    expect(candidatesFor(identity(false), [], [candidate("Acme", false)])).toEqual([]);
  });

  it("keeps linked Persons even when the email is unverified", () => {
    expect(candidatesFor(identity(false), [candidate("Acme", true)], [])).toEqual([candidate("Acme", true)]);
  });

  it("offers one Person per Organization, preferring the linked one, sorted by name", () => {
    expect(
      candidatesFor(identity(true), [candidate("Globex", true)], [candidate("Globex", false), candidate("Acme", false)]),
    ).toEqual([candidate("Acme", false), candidate("Globex", true)]);
  });
});

describe("decideSignIn", () => {
  it("enters the only candidate", () => {
    expect(decideSignIn(identity(true), [candidate("Acme", false)], nobody)).toEqual({
      _tag: "Enter",
      candidate: candidate("Acme", false),
    });
  });

  it("asks to choose between several", () => {
    expect(decideSignIn(identity(true), [candidate("Acme", true), candidate("Globex", false)], nobody)._tag).toBe(
      "ChooseOrganization",
    );
  });

  it("offers creation only to a verified allowlisted email", () => {
    const allowlist = new OrganizationCreationAllowlist(" ADA@example.com ,, grace@example.com");
    expect(decideSignIn(identity(true), [], allowlist)._tag).toBe("CreateOrganization");
    expect(decideSignIn(identity(false), [], allowlist)._tag).toBe("NotInOrganization");
    expect(decideSignIn(identity(true, "eve@example.com"), [], allowlist)._tag).toBe("NotInOrganization");
    expect(decideSignIn(identity(true), [], nobody)._tag).toBe("NotInOrganization");
  });
});

